DROP TABLE IF EXISTS `patent_attorneys`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patent_attorneys` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '변리사 고유 ID (PK)',
  `name` varchar(50) NOT NULL COMMENT '성명',
  `status` int DEFAULT NULL COMMENT '상태 (1: 개업, 0: 휴업, -1: 폐업)',
  `office` varchar(100) DEFAULT NULL COMMENT '사무소명',
  `addr` varchar(150) DEFAULT NULL COMMENT '주소',
  `phone` varchar(30) DEFAULT NULL COMMENT '연락처',
  `field` varchar(20) NOT NULL COMMENT '전문분야 코드 (ELEC, CHEM, MECH, DESIGN)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성일시',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정일시',
  `rating` decimal(2,1) DEFAULT NULL COMMENT '평점 (0.0 ~ 5.0)',
  `consult_time` varchar(20) DEFAULT NULL COMMENT '상담 가능 시간',
  `experience_years` int DEFAULT NULL COMMENT '경력 (년)',
  `price` int DEFAULT NULL COMMENT '상담 비용',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2829 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='변리사 정보 테이블';
